Trigger.script:
Yso = Yso or {} Yso._predict = Yso._predict or { last = 0 }
local now = (type(getEpoch)=="function" and getEpoch()) or os.time() if (now - (Yso._predict.last or 0)) < 5 then return end Yso._predict.last = now
-- NOTE: If you do not have a client-side 'curing predict' alias, the -- in-game command is typically: CURING AFFLICTIONS ADD <affliction>. send("curing predict brokenleftleg") send("curing predict brokenrightleg")

Yso = Yso or {}
Yso.magi = Yso.magi or {}
Yso.magi.energy = true
deleteLine()
cecho("\n<SteelBlue>[Magi] <ansi_light_magenta>(HEAL BURST READY!).\n")

Yso = Yso or {}
Yso.magi = Yso.magi or {}
Yso.magi.energy = false
deleteLine()
cecho("\n<SteelBlue>[Magi] <ansi_light_red>(HEAL BURST USED!).\n")
cecho("<SteelBlue>[Magi] <ansi_light_red>(EMBED ENERGISE!).\n")

Yso.dragon.state.purge=true
local aff=Legacy and Legacy.Curing and Legacy.Curing.Affs or {}
if aff.softlocked==true then Yso.dragon.emit("dragonheal","eq","cure") end

Alias.script:
Yso = Yso or {} Yso.util = Yso.util or {}
if type(Yso.util.toggle_route_alias) ~= "function" then cecho("<orange>[YSO] route controller unavailable; check Mudlet load order.<reset>\n") return end
local ok, why = Yso.util.toggle_route_alias("magi_firestorm", "alias:fstorm") if ok ~= true then cecho("<SlateBlue>[YSO] fstorm toggle failed: " .. tostring(why or "unknown") .. "<reset>\n") end

Yso = Yso or {} Yso.util = Yso.util or {}
if type(Yso.util.toggle_route_alias) ~= "function" then cecho("<orange>[YSO] route controller unavailable; check Mudlet load order.<reset>\n") return end
local ok, why = Yso.util.toggle_route_alias("magi_water_group", "alias:gwater") if ok ~= true then cecho("<SlateBlue>[YSO] gwater toggle failed: " .. tostring(why or "unknown") .. "<reset>\n") end

local targets = {}
for i = 2, 4 do local tgt = matches[i] if tgt and tgt ~= "" then targets[#targets + 1] = tgt end end
if #targets > 0 then send("queue prepend eqbal cast stormhammer at " .. table.concat(targets, " and ")) end

local crystals = { "cube", "cylinder", "diamond", "disc", "egg", "pentagon", "polyhedron", "pyramid", "sphere", "spiral", "torus" }
for _, shape in ipairs(crystals) do send("outr " .. shape) end
for _, shape in ipairs(crystals) do send("spin " .. shape) end

Script.script:
Yso = Yso or {}
Yso.magi = Yso.magi or {}
Yso.magi.defs = Yso.magi.defs or {}

local M = Yso.magi.defs

M.state = M.state or {
  class_name = "",
}

local function _vitals()
  return (gmcp and gmcp.Char and gmcp.Char.Vitals) or {}
end

local function _status()
  return (gmcp and gmcp.Char and gmcp.Char.Status) or {}
end

function M.get_hp_percent()
  local v = _vitals()
  local hp = tonumber(v.hp)
  local maxhp = tonumber(v.maxhp)

  if not hp or not maxhp or maxhp <= 0 then
    return nil
  end

  return (hp / maxhp) * 100
end

function M.get_class()
  local s = _status()
  local cls = s.class or s.classname or M.state.class_name or ""
  return tostring(cls)
end

function M.is_magi()
  return M.get_class():lower() == "magi"
end

function M.set_class(classname)
  M.state.class_name = tostring(classname or "")
end

Yso = Yso or {}
Yso.alc = Yso.alc or {}
Yso.alc.form = Yso.alc.form or {}

function Yso.alc.form.handle_phiallist_line(line)
  if type(Yso.alc.form.parse_phiallist) ~= "function" then
    return nil
  end
  return Yso.alc.form.parse_phiallist(line)
end

-- Affliction-to-venom mapping; paired Dragoncurse strategy remains explicit.
affs2rend = {sensitivity="prefarar", impatience="slike", paralysis="curare",
  asthma="kalmia", stupidity="xentio", weariness="vernalius", recklessness="eurypteria"}
